&reftitle.returnvalues;

 Devuelve &true; en caso de éxito (incluso cuando el fichero ya estaba
 cargado), o &false; en caso de error.

  &reftitle.examples;

   Ejemplo de Yaf_Loader::import


<?php
class Bootstrap extends Yaf_Bootstrap_Abstract
{
    public function _initHelpers()
    {
        /* una ruta relativa se busca dentro del directorio de la biblioteca,
         * es decir, APPLICATION_PATH/library/functions/format.php */
        Yaf_Loader::import("functions/format.php");
    }
}
?>




   Un fichero solo se importa una vez


<?php
/* una ruta absoluta se usa tal cual */
Yaf_Loader::import("/var/www/shop/application/library/Legacy/csv_export.php");

/* importar de nuevo el mismo fichero no hace nada y devuelve true */
var_dump(
    Yaf_Loader::import("/var/www/shop/application/library/Legacy/csv_export.php")
);
?>


